import{_ as e,o as t,c as _,a3 as s}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-099.Dp71fPUt.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/73-“上流”善交际，“下流”不标显.md","filePath":"books/xialiu-shehui/73-“上流”善交际，“下流”不标显.md","lastUpdated":1794732511000}'),p={name:"books/xialiu-shehui/73-“上流”善交际，“下流”不标显.md"};function i(r,a,l,n,d,c){return t(),_("div",null,[...a[0]||(a[0]=[s('<h2 id="上流-善交际-下流-不标显" tabindex="-1">“上流”善交际，“下流”不标显 <a class="header-anchor" href="#上流-善交际-下流-不标显" aria-label="Permalink to &quot;“上流”善交际，“下流”不标显&quot;">​</a></h2><p>从“第一次女性阶层化调查”的结果可以得知，性格在一定程度上也体现了阶层的差异。</p><p>当被问及用什么词句可以表现“自我风采”时，回答“善于交际”的18—37岁的女性当中，属于上流阶层的占29.6%，属于中流阶层和下流阶层的各占19.5%和15.8%。同样，回答“性格开朗”的该年龄层女性中，“上流”“中流”以及“下流”所占的比例分别是41.3%、37.4%和29.3%。此外，选择“朝气蓬勃”“自己有明确的想法”“主张自我”“大胆”“敢为人先、具有领导魄力”“喜欢照顾别人、体贴”“坚忍”等具有领导者色彩的性格的，也是上流阶层的女性居多（见表7-2）。</p><p>表7-2　不同的阶层表现“自我风采”的词汇（主要选项）</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、读卖广告社共同实施的“第一次女性阶层化调查”</p><p>但同时，在一直以来为女性所追求的价值观方面，诸如“有女人味、女性化”“品行端正”“性感”“理性”“举止彬彬有礼”“气质优雅”等选项，也是上流阶层的女性选择更多。</p><p>此外，选择“都市化”“时髦”“做事利索”“精力充沛”“沉稳”“聪明”等词汇的同样也是上流阶层的女性居多，而这些选项给人的印象则是在工作方面很能干。</p><p>与此相对的则是，下流阶层女性所选的大多是“悠闲自得”“不标显”“朴素”，只有少部分人选择“敢为人先、具有领导魄力”“有女人味、女性化”“品行端正”“性感”“理性”“都市化”“气质优雅”“沉稳”“做事利索”“善于交际”等。</p>',9)])])}const m=e(p,[["render",i]]);export{h as __pageData,m as default};
